package com.dymbia.sumaqagro.platform.farming.domain.model.commands;

import java.math.BigDecimal;
import java.time.LocalDate;

/**
 * Command to record the transport of inputs or harvest in a cost ledger.
 *
 * @param campaignLedgerId the ledger of the campaign
 * @param route            the route, such as "Chacra - centro de acopio"
 * @param cost             the cost of the transport
 * @param expenseDate      the date of the transport
 * @param clientSyncId     the id generated by the device in offline mode, optional
 */
public record RecordFieldFreightExpenseCommand(Long campaignLedgerId, String route, BigDecimal cost,
                                               LocalDate expenseDate, String clientSyncId) {
    public RecordFieldFreightExpenseCommand {
        if (campaignLedgerId == null || campaignLedgerId <= 0) {
            throw new IllegalArgumentException("campaign.ledger.error.id.invalid");
        }
    }
}